-- Previsões iniciais de exemplo (Modelo v6) para demonstração imediata
INSERT INTO resultados_previsoes_ia (
    request_id, reference_time, previous_reference_time,
    forecast_start, forecast_end, temperature_2m, relative_humidity_2m,
    pressure_msl, cloud_cover, pressure_msl_previous_hour,
    rain_probability, rain_predicted, source_record_id, previous_source_record_id
)
SELECT
    'a1111111-1111-4111-8111-111111111111'::uuid,
    t.time AT TIME ZONE 'UTC',
    t_prev.time AT TIME ZONE 'UTC',
    t.time AT TIME ZONE 'UTC',
    (t.time + INTERVAL '1 hour') AT TIME ZONE 'UTC',
    t.temperature_2m, t.relative_humidity_2m, t.pressure_msl, t.cloud_cover, t_prev.pressure_msl,
    0.70, true, t.id, t_prev.id
FROM dataset_weather_goes t
JOIN dataset_weather_goes t_prev ON t_prev.time = t.time - INTERVAL '1 hour'
WHERE t.time = '2026-09-30 13:00:00'
ON CONFLICT (request_id) DO NOTHING;

